            /// (authored, its layout frames, its shrink); authored and minimum at least.
            public List<Vector2> ladder;
        }
        private readonly Dictionary<string, Entry> _byKey = new Dictionary<string, Entry>(StringComparer.OrdinalIgnoreCase);

        public static readonly Vector2 DefaultAuthored = new Vector2(3.0f, 3.6f);
        public static readonly Vector2 DefaultMinimum = new Vector2(2.0f, 2.4f);

        public int Count => _byKey.Count;

        /// Registers one attraction under every key it can be named by
        /// (occurrence id, address, resource name, leaf), scoped to its title
        /// and unscoped. `minimum` zero = the authored size.
        public void Add(string contentId, Vector2 authored, Vector2 minimum, params string[] keys)
            => AddLadder(contentId, authored, new List<Vector2> { minimum }, keys);

        /// `sizes` = the smaller layout sizes (frames, shrink), any order.
        public void AddLadder(string contentId, Vector2 authored, List<Vector2> sizes, params string[] keys)
        {
            if (!(authored.x > 0.05f && authored.y > 0.05f)) return;
            var ladder = new List<Vector2> { authored };
            if (sizes != null)
                foreach (Vector2 v in sizes)
                {
                    if (!(v.x > 0.05f && v.y > 0.05f) || v.x * v.y > authored.x * authored.y + 1e-4f) continue;
                    bool dup = false;
                    foreach (Vector2 u in ladder) if (Mathf.Abs(u.x - v.x) < 0.01f && Mathf.Abs(u.y - v.y) < 0.01f) dup = true;
                    if (!dup) ladder.Add(v);
                }
            ladder.Sort((a, b) => (b.x * b.y).CompareTo(a.x * a.y));
            var e = new Entry { authored = authored, minimum = ladder[ladder.Count - 1], ladder = ladder };
            foreach (string k in keys)
            {
                if (string.IsNullOrEmpty(k)) continue;
                foreach (string kk in new[] { k, PlaylistPacker.Leaf(k) })
                {
                    if (!string.IsNullOrEmpty(contentId) && !_byKey.ContainsKey(contentId + "|" + kk)) _byKey[contentId + "|" + kk] = e;
                    if (!_byKey.ContainsKey("|" + kk)) _byKey["|" + kk] = e;
                }
            }
        }

        public bool TryGet(string contentId, PlaylistItemRef item, out Entry e)
        {
            foreach (string k in new[] { item.occurrenceId, item.resourceAddress, item.resourceName, item.attraction,
                         PlaylistPacker.Leaf(item.resourceAddress), PlaylistPacker.Leaf(item.resourceName), PlaylistPacker.Leaf(item.attraction) })
            {
                if (string.IsNullOrEmpty(k)) continue;
                if (!string.IsNullOrEmpty(contentId) && _byKey.TryGetValue(contentId + "|" + k, out e)) return true;
                if (_byKey.TryGetValue("|" + k, out e)) return true;
            }
            e = default;
            return false;
        }
    }

