    public sealed class PlaylistRoomGraph
    {
        public readonly List<PlaylistRoomNode> nodes = new List<PlaylistRoomNode>();
        public readonly List<PlaylistRoomEdge> edges = new List<PlaylistRoomEdge>();
        public readonly List<List<PlaylistRoomEdge>> adj = new List<List<PlaylistRoomEdge>>();
        public int entrance = -1;
        public Vector2 entrancePoint;

        public const float TouchGapM = 0.35f;
        public const float DoorProbeM = 0.5f;
        public const float DoorReachM = 0.9f;
        public const int MaxRectsPerRoom = 12;
        public const float MinRectSideM = 0.9f;

        private float[,] _dist;
        private int[,] _next;

        /// Shortest walking cost between two rooms (edge costs), +inf when apart.
        public float Dist(int a, int b) { AllPairs(); return _dist[a, b]; }

        /// The rooms a shortest walk from a to b passes through, a and b included.
        public List<int> Walk(int a, int b)
        {
            AllPairs();
            var w = new List<int> { a };
            if (a == b || _next[a, b] < 0) { if (a != b) w.Add(b); return w; }
            int u = a;
            while (u != b && w.Count <= nodes.Count) { u = _next[u, b]; w.Add(u); }
            return w;
        }

        private void AllPairs()
        {
            if (_dist != null) return;
            int n = nodes.Count;
            _dist = new float[n, n]; _next = new int[n, n];
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++) { _dist[i, j] = i == j ? 0f : float.PositiveInfinity; _next[i, j] = i == j ? i : -1; }
            foreach (var e in edges)
            {
                if (e.cost < _dist[e.a, e.b]) { _dist[e.a, e.b] = _dist[e.b, e.a] = e.cost; _next[e.a, e.b] = e.b; _next[e.b, e.a] = e.a; }
            }
            for (int k = 0; k < n; k++)
                for (int i = 0; i < n; i++)
                    for (int j = 0; j < n; j++)
                        if (_dist[i, k] + _dist[k, j] < _dist[i, j] - 1e-4f) { _dist[i, j] = _dist[i, k] + _dist[k, j]; _next[i, j] = _next[i, k]; }
        }

        public PlaylistRoomEdge Edge(int a, int b)
        {
            if (a < 0 || a >= adj.Count) return null;
            foreach (var e in adj[a]) if (e.Other(a) == b) return e;
            return null;
        }

        public static PlaylistRoomGraph Build(SpaceMapData map)
        {
            var g = new PlaylistRoomGraph();
            if (map?.rooms == null) return g;
            var rectRoom = new Dictionary<string, int>(StringComparer.Ordinal);
            foreach (SpaceRoom room in map.rooms)
            {
                if (room == null) continue;
                var n = new PlaylistRoomNode { room = room, roomId = room.roomId ?? ("room" + g.nodes.Count), label = room.label ?? room.kind ?? "", storyId = room.storyId ?? "L0" };
                var rs = new List<SpaceRect>();
                foreach (SpaceRect r in room.rects)
                    if (r != null && r.w >= MinRectSideM && r.d >= MinRectSideM) rs.Add(r);
                if (rs.Count == 0) continue;
                rs.Sort((x, y) => { int c = y.Area.CompareTo(x.Area); return c != 0 ? c : string.CompareOrdinal(x.rectId, y.rectId); });
                float area = 0f; Vector2 acc = Vector2.zero;
                n.min = new Vector2(float.MaxValue, float.MaxValue); n.max = new Vector2(float.MinValue, float.MinValue);
                foreach (SpaceRect r in rs)
                {
                    area += r.Area; acc += r.Center * r.Area;
                    for (int c = 0; c < 4; c++) { Vector2 p = r.Corner(c); n.min = Vector2.Min(n.min, p); n.max = Vector2.Max(n.max, p); }
                }
                n.usableArea = area;
                n.largestRectArea = rs[0].Area;
                n.centroid = acc / Mathf.Max(area, 1e-4f);
                for (int i = 0; i < rs.Count && i < MaxRectsPerRoom; i++) n.rects.Add(rs[i]);
                n.index = g.nodes.Count;
                g.nodes.Add(n);
                g.adj.Add(new List<PlaylistRoomEdge>());
                foreach (SpaceRect r in room.rects) if (r?.rectId != null) rectRoom[r.rectId] = n.index;
            }
            if (g.nodes.Count == 0) return g;

            InferOutdoor(g, map);
            var walls = new List<SpaceWall>();
            var doors = new List<SpaceWall>();
            foreach (SpaceRoom room in map.rooms) if (room != null) foreach (SpaceWall w in room.walls) Sort(w, walls, doors);
            foreach (SpaceWall w in map.roomPlanSurfaces) Sort(w, walls, doors);

            // (a) rect edge spans touching a rect of another room.
            foreach (var n in g.nodes)
                foreach (SpaceRect r in n.room.rects)
                {
                    if (r?.borders == null) continue;
                    EdgeSpans(g, n.index, r, r.borders.minX, r.d, rectRoom, (t) => new Vector2(r.x, r.z + t));
                    EdgeSpans(g, n.index, r, r.borders.maxX, r.d, rectRoom, (t) => new Vector2(r.x + r.w, r.z + t));
                    EdgeSpans(g, n.index, r, r.borders.minZ, r.w, rectRoom, (t) => new Vector2(r.x + t, r.z));
                    EdgeSpans(g, n.index, r, r.borders.maxZ, r.w, rectRoom, (t) => new Vector2(r.x + t, r.z + r.d));
                }
            // (b) RoomPlan doors / openings between two rooms.
            foreach (SpaceWall d in doors)
            {
                var p = new Vector2(d.center.x, d.center.z);
                var nn = new Vector2(d.normal.x, d.normal.z);
                if (nn.sqrMagnitude < 1e-4f) continue;
                nn.Normalize();
                int ra = RoomOnSide(g, p, nn), rb = RoomOnSide(g, p, -nn);
                if (ra >= 0 && rb >= 0 && ra != rb) g.Connect(ra, rb, "door", p);
            }
            // (c) rooms that touch with no wall between them (open plan).
            for (int i = 0; i < g.nodes.Count; i++)
                for (int j = i + 1; j < g.nodes.Count; j++)
                {
                    if (g.Edge(i, j) != null) continue;
                    if (!SharedBoundary(g.nodes[i], g.nodes[j], out Vector2 sa, out Vector2 sb)) continue;
                    // Open only where some of the shared boundary has no wall on it.
                    bool open = false; Vector2 mid = (sa + sb) * 0.5f;
                    for (int q = 0; q <= 6 && !open; q++)
                    {
                        Vector2 sp = Vector2.Lerp(sa, sb, (q + 0.5f) / 7f);
                        if (!WallNear(walls, sp, 0.3f)) { open = true; mid = sp; }
                    }
                    if (open) g.Connect(i, j, "open", mid);
                }
            // Entrance: the room holding spawn, else the nearest.
            var spawn = new Vector2(map.spawn.x, map.spawn.z);
            g.entrance = RoomAt(g, spawn);
            if (g.entrance < 0)
            {
                float best = float.MaxValue;
                foreach (var n in g.nodes)
                {
                    float dd = DistToRoom(n, spawn);
                    if (dd < best) { best = dd; g.entrance = n.index; }
                }
            }
            g.entrancePoint = spawn;
            // (d) islands: join each to the main component at its nearest gap.
            while (true)
            {
                var comp = g.Component(g.entrance);
                if (comp.Count == g.nodes.Count) break;
                float best = float.MaxValue; int bi = -1, bj = -1; Vector2 bp = default;
                foreach (int i in comp)
                    for (int j = 0; j < g.nodes.Count; j++)
                    {
                        if (comp.Contains(j)) continue;
                        if (!ClosestRects(g.nodes[i], g.nodes[j], out Vector2 pa, out Vector2 pb, out float gap)) continue;
                        if (gap < best - 1e-4f) { best = gap; bi = i; bj = j; bp = (pa + pb) * 0.5f; }
                    }
                if (bi < 0) break;
                g.Connect(bi, bj, "inferred", bp);
            }
            // Walk distances from the entrance (Dijkstra; n is small).
            foreach (var n in g.nodes) { n.walkM = float.MaxValue; n.hops = int.MaxValue; }
            g.nodes[g.entrance].walkM = 0f; g.nodes[g.entrance].hops = 0;
            var done = new bool[g.nodes.Count];
            for (int it = 0; it < g.nodes.Count; it++)
            {
                int u = -1;
                for (int i = 0; i < g.nodes.Count; i++) if (!done[i] && g.nodes[i].walkM < float.MaxValue && (u < 0 || g.nodes[i].walkM < g.nodes[u].walkM)) u = i;
                if (u < 0) break;
                done[u] = true;
                foreach (var e in g.adj[u])
                {
                    int v = e.Other(u);
                    if (g.nodes[u].walkM + e.cost < g.nodes[v].walkM) { g.nodes[v].walkM = g.nodes[u].walkM + e.cost; g.nodes[v].hops = g.nodes[u].hops + 1; }
                }
            }
            foreach (var n in g.nodes) n.drama = Drama(n);
            NameRooms(g);
            return g;
        }

        private static void Sort(SpaceWall w, List<SpaceWall> walls, List<SpaceWall> doors)
        {
            if (w == null) return;
            if (w.kind == "door" || w.kind == "opening") doors.Add(w);
            else if (w.kind == "wall" || w.kind == "window") walls.Add(w);
        }

        private void Connect(int a, int b, string kind, Vector2 door)
        {
            if (a == b) return;
            PlaylistRoomEdge existing = Edge(a, b);
            int rank(string k) => k == "door" ? 3 : k == "open" ? 2 : k == "adjacent" ? 1 : 0;
            if (existing != null)
            {
                if (rank(kind) > rank(existing.kind)) { existing.kind = kind; existing.door = door; existing.cost = Cost(a, b, door, kind); }
                return;
            }
            var e = new PlaylistRoomEdge { a = Math.Min(a, b), b = Math.Max(a, b), kind = kind, door = door, cost = Cost(a, b, door, kind) };
            edges.Add(e); adj[a].Add(e); adj[b].Add(e);
        }

        private float Cost(int a, int b, Vector2 door, string kind)
        {
            float c = Vector2.Distance(nodes[a].centroid, door) + Vector2.Distance(door, nodes[b].centroid);
            if (nodes[a].storyId != nodes[b].storyId) c = c * 2f + 6f;
            if (kind == "inferred") c = c * 1.5f + 2f;
            return c;
        }

        private HashSet<int> Component(int start)
        {
            var seen = new HashSet<int> { start };
            var q = new Queue<int>(); q.Enqueue(start);
            while (q.Count > 0) { int u = q.Dequeue(); foreach (var e in adj[u]) if (seen.Add(e.Other(u))) q.Enqueue(e.Other(u)); }
            return seen;
        }

        private static void EdgeSpans(PlaylistRoomGraph g, int self, SpaceRect r, RectEdgeBorder edge, float len,
            Dictionary<string, int> rectRoom, Func<float, Vector2> local)
        {
            if (!edge.IsComputed) return;
            foreach (RectSpan s in edge.SpansFor(len))
            {
                if (string.IsNullOrEmpty(s.touches) || s.IsWall) continue;
                if (!rectRoom.TryGetValue(s.touches, out int other) || other == self) continue;
                g.Connect(self, other, s.IsDoorway ? "door" : "adjacent", r.RectToPark(local(s.Center)));
            }
        }

        /// The room a step through a door lands in on the `n` side: the nearest
        /// room (within 3 m of the probe) whose floor lies on that side — a door
        /// can stand a little off the rects (furniture).
        private static int RoomOnSide(PlaylistRoomGraph g, Vector2 door, Vector2 n)
        {
            int best = -1; float bestD = 3f;
            foreach (var node in g.nodes)
            {
                if (Vector2.Dot(node.centroid - door, n) <= 0f) continue;
                float d = DistToRoom(node, door + n * DoorProbeM);
                if (d < bestD - 1e-5f) { bestD = d; best = node.index; }
            }
            return best;
        }

        internal static int RoomAt(PlaylistRoomGraph g, Vector2 p)
        {
            int best = -1; float bestD = float.MaxValue;
            foreach (var n in g.nodes)
            {
                float d = DistToRoom(n, p);
                if (d < bestD - 1e-5f) { bestD = d; best = n.index; }
            }
            return bestD <= DoorReachM ? best : -1;
        }

        internal static float DistToRoom(PlaylistRoomNode n, Vector2 p)
        {
            float best = float.MaxValue;
            foreach (SpaceRect r in n.room.rects)
            {
                if (r == null || r.w <= 0f || r.d <= 0f) continue;
                Vector2 q = r.ParkToRect(p);
                float dx = Mathf.Max(r.x - q.x, 0f, q.x - (r.x + r.w));
                float dz = Mathf.Max(r.z - q.y, 0f, q.y - (r.z + r.d));
                best = Mathf.Min(best, Mathf.Sqrt(dx * dx + dz * dz));
            }
            return best;
        }

        private static bool ClosestRects(PlaylistRoomNode a, PlaylistRoomNode b, out Vector2 pa, out Vector2 pb, out float gap)
        {
            pa = pb = default; gap = float.MaxValue;
            if (a.storyId != b.storyId) return false;
            foreach (SpaceRect ra in a.room.rects)
                foreach (SpaceRect rb in b.room.rects)
                {
                    if (ra == null || rb == null || ra.w <= 0 || rb.w <= 0) continue;
                    AABB(ra, out Vector2 amin, out Vector2 amax);
                    AABB(rb, out Vector2 bmin, out Vector2 bmax);
                    float dx = Mathf.Max(bmin.x - amax.x, amin.x - bmax.x, 0f);
                    float dz = Mathf.Max(bmin.y - amax.y, amin.y - bmax.y, 0f);
                    float d = Mathf.Sqrt(dx * dx + dz * dz);
                    if (d >= gap) continue;
                    gap = d;
                    // Closest points: clamp each box's centre into the other.
                    Vector2 ca = (amin + amax) * 0.5f, cb = (bmin + bmax) * 0.5f;
                    pa = new Vector2(Mathf.Clamp(cb.x, amin.x, amax.x), Mathf.Clamp(cb.y, amin.y, amax.y));
                    pb = new Vector2(Mathf.Clamp(ca.x, bmin.x, bmax.x), Mathf.Clamp(ca.y, bmin.y, bmax.y));
                    pa = new Vector2(Mathf.Clamp(pb.x, amin.x, amax.x), Mathf.Clamp(pb.y, amin.y, amax.y));
                }
            return gap < float.MaxValue;
        }

        /// Two rooms whose rects touch (gap ≤ TouchGapM) along at least
        /// MinSharedM of boundary — a corner touch is not a way through.
        public const float MinSharedM = 0.7f;
        private static bool SharedBoundary(PlaylistRoomNode a, PlaylistRoomNode b, out Vector2 sa, out Vector2 sb)
        {
            sa = sb = default;
            if (a.storyId != b.storyId) return false;
            float best = 0f;
            foreach (SpaceRect ra in a.room.rects)
                foreach (SpaceRect rb in b.room.rects)
                {
                    if (ra == null || rb == null || ra.w <= 0 || rb.w <= 0) continue;
                    AABB(ra, out Vector2 amin, out Vector2 amax);
                    AABB(rb, out Vector2 bmin, out Vector2 bmax);
                    float gx = Mathf.Max(bmin.x - amax.x, amin.x - bmax.x);   // > 0: apart along x
                    float gz = Mathf.Max(bmin.y - amax.y, amin.y - bmax.y);
                    float ox = Mathf.Min(amax.x, bmax.x) - Mathf.Max(amin.x, bmin.x);
                    float oz = Mathf.Min(amax.y, bmax.y) - Mathf.Max(amin.y, bmin.y);
                    if (gx > TouchGapM || gz > TouchGapM) continue;
                    // Side by side in x (a vertical seam): the shared run is the z overlap.
                    if (gx >= gz && oz > best)
                    {
                        best = oz; float x = gx > 0 ? (amax.x < bmin.x ? (amax.x + bmin.x) / 2 : (bmax.x + amin.x) / 2) : (Mathf.Abs(amax.x - bmin.x) < Mathf.Abs(bmax.x - amin.x) ? amax.x : amin.x);
                        sa = new Vector2(x, Mathf.Max(amin.y, bmin.y)); sb = new Vector2(x, Mathf.Min(amax.y, bmax.y));
                    }
                    else if (gz > gx && ox > best)
                    {
                        best = ox; float z = gz > 0 ? (amax.y < bmin.y ? (amax.y + bmin.y) / 2 : (bmax.y + amin.y) / 2) : (Mathf.Abs(amax.y - bmin.y) < Mathf.Abs(bmax.y - amin.y) ? amax.y : amin.y);
                        sa = new Vector2(Mathf.Max(amin.x, bmin.x), z); sb = new Vector2(Mathf.Min(amax.x, bmax.x), z);
                    }
                }
            return best >= MinSharedM;
        }

        private static void AABB(SpaceRect r, out Vector2 min, out Vector2 max)
        {
            min = new Vector2(float.MaxValue, float.MaxValue); max = new Vector2(float.MinValue, float.MinValue);
            for (int c = 0; c < 4; c++) { Vector2 p = r.Corner(c); min = Vector2.Min(min, p); max = Vector2.Max(max, p); }
        }

        private static bool WallNear(List<SpaceWall> walls, Vector2 p, float within)
        {
            foreach (SpaceWall w in walls)
            {
                var c = new Vector2(w.center.x, w.center.z);
                var n = new Vector2(w.normal.x, w.normal.z);
                if (n.sqrMagnitude < 1e-4f) continue;
                n.Normalize();
                var t = new Vector2(-n.y, n.x);
                Vector2 a = c - t * (w.w * 0.5f), b = c + t * (w.w * 0.5f);
                Vector2 ab = b - a;
                float k = ab.sqrMagnitude > 1e-6f ? Mathf.Clamp01(Vector2.Dot(p - a, ab) / ab.sqrMagnitude) : 0f;
                if (Vector2.Distance(p, a + ab * k) <= within) return true;
            }
            return false;
        }

        private static readonly string[] OutdoorWords = { "backyard", "yard", "garden", "patio", "deck", "lawn", "outdoor", "outside", "park", "field", "porch", "terrace", "playground" };

        internal static bool LabelSaysOutdoor(string label)
        {
            if (string.IsNullOrEmpty(label)) return false;
            string l = label.ToLowerInvariant();
            foreach (string w in OutdoorWords) if (l.Contains(w)) return true;
            return false;
        }

        /// Outdoor is inferred (no RoomPlan word for it): an outdoor label, or
        /// non-architectural ground with no wall anywhere near it — outside the
        /// RoomPlan walls' bounds when the scan has any.
        private static void InferOutdoor(PlaylistRoomGraph g, SpaceMapData map)
        {
            bool anyWall = false; Vector2 wmin = new Vector2(float.MaxValue, float.MaxValue), wmax = new Vector2(float.MinValue, float.MinValue);
            void addWall(SpaceWall w)
            {
                if (w == null || w.kind != "wall") return;
                anyWall = true;
                var c = new Vector2(w.center.x, w.center.z);
                wmin = Vector2.Min(wmin, c - Vector2.one * (w.w * 0.5f)); wmax = Vector2.Max(wmax, c + Vector2.one * (w.w * 0.5f));
            }
            foreach (SpaceWall w in map.roomPlanSurfaces) addWall(w);
            foreach (SpaceRoom r in map.rooms) if (r != null) foreach (SpaceWall w in r.walls) addWall(w);
            foreach (var n in g.nodes)
            {
                SpaceRoom r = n.room;
                if (LabelSaysOutdoor(r.label) || LabelSaysOutdoor(r.kind)) { n.outdoor = true; continue; }
                if (!string.IsNullOrEmpty(r.label) || SpaceGroundMode.IsArchitectural(r.groundMode) || r.walls.Count > 0) continue;
                bool walled = false;
                foreach (SpaceRect rect in r.rects)
                    if (rect?.borders != null && (rect.borders.minX.WallShare > 0f || rect.borders.maxX.WallShare > 0f
                        || rect.borders.minZ.WallShare > 0f || rect.borders.maxZ.WallShare > 0f)) { walled = true; break; }
                if (walled) continue;
                bool groundOutside = r.groundMode == SpaceGroundMode.Terrain || r.groundMode == SpaceGroundMode.Flat
                    || (r.groundMode == null && !anyWall && n.usableArea >= 40f);
                if (!groundOutside) continue;
                if (anyWall)
                {
                    Vector2 c = n.centroid;
                    bool inside = c.x > wmin.x - 0.5f && c.x < wmax.x + 0.5f && c.y > wmin.y - 0.5f && c.y < wmax.y + 0.5f;
                    if (inside) continue;
                }
                n.outdoor = true;
            }
        }

        internal static int LabelBonus(string label)
        {
            string l = (label ?? "").ToLowerInvariant().Replace("_", "").Replace(" ", "");
            if (l.Contains("bath") || l.Contains("toilet") || l.Contains("laundry")) return -30;
            if (l.Contains("hall") && !l.Contains("arcade")) return -12;
            if (l.Contains("stair")) return -20;
            if (l.Contains("kitchen")) return -4;
            if (l.Contains("living") || l.Contains("family") || l.Contains("great") || l.Contains("garage")
                || l.Contains("basement") || l.Contains("party") || l.Contains("gym") || l.Contains("arcade")
                || l.Contains("court") || l.Contains("ballroom")) return 8;
            return 0;
        }

        private static float Drama(PlaylistRoomNode n) =>
            n.largestRectArea + 0.25f * n.usableArea + (n.outdoor ? 20f : 0f) + LabelBonus(n.label);

        /// What Dreamie can say: the RoomPlan label in words, else a name from
        /// where the room is ("front room" = the entrance, "backyard").
        private static void NameRooms(PlaylistRoomGraph g)
        {
            // "Indoor" for naming = proven: a label, walls or a built floor.
            bool anyIndoor = false; int indoorCount = 0;
            foreach (var n in g.nodes)
                if (!n.outdoor && (!string.IsNullOrEmpty(n.label) || n.room.walls.Count > 0 || SpaceGroundMode.IsArchitectural(n.room.groundMode)))
                { anyIndoor = true; indoorCount++; }
            int farthest = -1, biggest = -1, bigOut = -1;
            foreach (var n in g.nodes)
                if (n.outdoor && string.IsNullOrEmpty(n.label) && (bigOut < 0 || n.usableArea > g.nodes[bigOut].usableArea)) bigOut = n.index;
            foreach (var n in g.nodes)
            {
                if (n.outdoor || !string.IsNullOrEmpty(n.label) || n.index == g.entrance) continue;
                if (farthest < 0 || n.walkM > g.nodes[farthest].walkM) farthest = n.index;
                if (biggest < 0 || n.usableArea > g.nodes[biggest].usableArea) biggest = n.index;
            }
            var used = new Dictionary<string, int>(StringComparer.Ordinal);
            foreach (var n in g.nodes)
            {
                string name;
                if (!string.IsNullOrEmpty(n.label)) name = Words(n.label);
                else if (n.outdoor) name = n.index == bigOut ? (anyIndoor ? "backyard" : n.usableArea >= 150f ? "park" : "yard") : (anyIndoor ? "side yard" : "lawn");
                else if (indoorCount <= 1 && g.nodes.Count == 1) name = n.usableArea >= 40f ? "big room" : "room";
                else if (n.index == g.entrance) name = "front room";
                else if (n.index == biggest && n.usableArea >= 20f) name = "big room";
                else if (n.index == farthest) name = "back room";
                else name = "side room";
                if (used.TryGetValue(name, out int c)) { used[name] = c + 1; name = name + " " + (c + 1); }
                else used[name] = 1;
                n.name = name;
            }
        }

        /// "livingRoom" / "living_room" → "living room".
        internal static string Words(string label)
        {
            var sb = new StringBuilder();
            for (int i = 0; i < label.Length; i++)
            {
                char ch = label[i];
                if (ch == '_' || ch == '-') { sb.Append(' '); continue; }
                if (char.IsUpper(ch) && i > 0 && sb.Length > 0 && sb[sb.Length - 1] != ' ') sb.Append(' ');
                sb.Append(char.ToLowerInvariant(ch));
            }
            return sb.ToString().Trim();
        }
    }

    // ── Plan (output) ────────────────────────────────────────────────────

    public sealed class PlaylistPlacedStop
    {
        public int order, leg, indexInLeg;
        public string role, beat, legId, legName, contentId, prefer;
        public string attraction, placed, resourceAddress, variant = "none";
        /// The stop's anchor id (SpaceMapPacked.occurrenceId, the runner's and the
        /// tour's key): `pl-{playlistId}-{leg}-{stop}` — unique even when a prefab
        /// plays in two legs.
        public string occurrenceId;
        /// The manifest occurrence of the attraction placed (main or alternate).
        public string manifestOccurrenceId;
        /// Spawned when its leg's package commits (false = streamed in later in the leg).
        public bool Standing => placedOk && !streamed;
        public string roomId, roomName, roomLabel, rectId, storyId;
        public int roomIndex = -1;   // graph node
        public int routeIndex = -1;  // index in the route (−1 off-route)
        public bool placedOk, streamed, homeReturn, offRoute;
        public Vector2 center, size;  // park-local centre; size on the rect's axes
        public float y, yawDeg;
        public Vector2 face;
        public int loadAt, unloadAt = -1;
        /// The authored stop's opaque options (JSON text), or null.
        public string options;
        /// The authored stop's challenge kind / bonus / reveal tip, and the main attraction's Web id.
        public string challenge, introHint, authoredAttractionId;
        public List<string> bonus = new List<string>();
        /// A platform bookend (Start Lobby / Results Room, PLAYLISTS.md § 11).
        public bool Bookend => PlaylistBookends.IsPlatformStop(contentId, placed ?? attraction);
        public readonly List<int> sharesWith = new List<int>();
        internal Vector2 local;       // rect-local centre
        internal SpaceRect rect;
    }

    public sealed class PlaylistPlannedLeg
    {
        public int leg;
        public string id, name, beat, next, nextApplied, walk = "forward", contentId;
        public bool degraded, titleSwitch;
        public float minutes;
        public string objectiveType, objectiveTarget;
        public int objectiveCount;
        public float objectiveSeconds;
        public readonly List<string> rooms = new List<string>();
        public readonly List<int> stops = new List<int>();
        public readonly List<int> loadAtStart = new List<int>();
        public readonly List<int> unloadAtStart = new List<int>();
        public readonly List<(int order, int after)> streamIn = new List<(int, int)>();
    }

    public sealed class PlaylistPlan
    {
        public const int PlannerVersion = 1;
        public string playlistId, contentId, name;
        public string status = "no-fit";   // ready | partial | no-fit
        public bool fits;
        public string fitReason = "";
        public int seed, variant, variantCount;
        public string layoutMode = "rooms"; // rooms | open | stream
        public float score;
        public string signature = "";
        public string entranceRoomId;
        public Vector2 entrancePoint;
        public readonly List<PlaylistRoomNode> route = new List<PlaylistRoomNode>();
        public readonly List<PlaylistPlacedStop> stops = new List<PlaylistPlacedStop>();
        public readonly List<PlaylistPlannedLeg> legs = new List<PlaylistPlannedLeg>();
        public readonly List<string> notes = new List<string>();
        public int backtracks;
        /// Times a leg's own walk re-enters a room it already left (must be 0).
        public int legReentries;
        public int climaxOrder = -1;
        public string climaxRoomId;
        public PlaylistRoomGraph graph;

        public string Summary()
        {
            var parts = new List<string>();
            string lastRoom = null;
            foreach (var s in stops)
            {
                if (!s.placedOk) continue;
                string label = PlaylistPacker.Pretty(s.placed);
                string what = s.order == 0 ? "Start: " + label
                    : s.order == climaxOrder ? "FINAL BOSS: " + label
                    : s.beat == "finale" ? "finale " + label : label;
                string where = s.roomName != lastRoom ? (s.homeReturn ? " back in the " : " in the ") + s.roomName : "";
                parts.Add(what + where);
                lastRoom = s.roomName;
            }
            return string.Join(" → ", parts);
        }

        /// `currentLeg`: the leg standing now (0-based; the queue's now-playing
        /// item; −1 = none yet), which sets each stop's `standing`.
        public JSONObject ToJson(int currentLeg = 0)
        {
            var o = new JSONObject();
            o.AddField("playlistId", playlistId ?? "");
            o.AddField("contentId", contentId ?? "");
            o.AddField("name", name ?? "");
            o.AddField("status", status);
            o.AddField("fits", fits);
            o.AddField("fitReason", fitReason ?? "");
            o.AddField("seed", seed);
            o.AddField("variant", variant);
            o.AddField("variantCount", variantCount);
            o.AddField("layoutMode", layoutMode);
            o.AddField("summary", Summary());
            o.AddField("signature", Hash(signature));
            var ent = new JSONObject();
            ent.AddField("roomId", entranceRoomId ?? "");
            ent.AddField("x", R(entrancePoint.x)); ent.AddField("z", R(entrancePoint.y));
            o.AddField("entrance", ent);
            var routeJ = new JSONObject(JSONObject.Type.Array);
            foreach (var n in route)
            {
                var r = new JSONObject();
                r.AddField("roomId", n.roomId); r.AddField("name", n.name); r.AddField("label", n.label ?? "");
                r.AddField("outdoor", n.outdoor); r.AddField("areaM2", R(n.usableArea)); r.AddField("storyId", n.storyId);
                routeJ.Add(r);
            }
            o.AddField("route", routeJ);
            var stopsJ = new JSONObject(JSONObject.Type.Array);
            foreach (var s in stops) stopsJ.Add(StopJson(s, currentLeg));
            o.AddField("currentLeg", currentLeg);
            o.AddField("stops", stopsJ);
            var legsJ = new JSONObject(JSONObject.Type.Array);
            foreach (var l in legs) legsJ.Add(LegJson(l));
            o.AddField("legs", legsJ);
            o.AddField("notes", Arr(notes));
            return o;
        }

        internal static JSONObject StopJson(PlaylistPlacedStop s, int currentLeg = -1)
        {
            var j = new JSONObject();
            j.AddField("order", s.order); j.AddField("leg", s.leg); j.AddField("legId", s.legId ?? ""); j.AddField("legName", s.legName ?? "");
            j.AddField("beat", s.beat ?? ""); j.AddField("role", s.role ?? "");
            if (!string.IsNullOrEmpty(s.contentId)) j.AddField("contentId", s.contentId);
            j.AddField("attraction", s.attraction ?? "");
            j.AddField("placed", s.placed ?? "");
            if (!string.IsNullOrEmpty(s.resourceAddress)) j.AddField("resourceAddress", s.resourceAddress);
            j.AddField("occurrenceId", s.occurrenceId ?? "");
            if (!string.IsNullOrEmpty(s.manifestOccurrenceId)) j.AddField("manifestOccurrenceId", s.manifestOccurrenceId);
            j.AddField("variant", s.variant);
            if (!string.IsNullOrEmpty(s.options))
            {
                JSONObject oj = null;
                try { oj = new JSONObject(s.options); } catch (Exception) { }
                if (oj != null && oj.type == JSONObject.Type.Object) j.AddField("options", oj);
                else j.AddField("options", s.options);
            }
            if (s.Bookend) j.AddField("bookend", true);
            if (s.placedOk)
            {
                j.AddField("roomId", s.roomId); j.AddField("roomName", s.roomName); j.AddField("routeIndex", s.routeIndex);
                j.AddField("rectId", s.rectId ?? "");
                j.AddField("cx", R(s.center.x)); j.AddField("cz", R(s.center.y)); j.AddField("y", R(s.y));
                j.AddField("w", R(s.size.x)); j.AddField("d", R(s.size.y)); j.AddField("yawDeg", R(s.yawDeg));
                j.AddField("storyId", s.storyId ?? "L0");
                j.AddField("faceX", R(s.face.x)); j.AddField("faceZ", R(s.face.y));
                j.AddField("roomLabel", s.roomLabel ?? "");
                var pj = new JSONObject(JSONObject.Type.Array); pj.Add(R(s.center.x)); pj.Add(R(s.y)); pj.Add(R(s.center.y));
                j.AddField("p", pj);
                var seat = new JSONObject();
                seat.AddField("x", R(s.center.x)); seat.AddField("y", R(s.y)); seat.AddField("z", R(s.center.y));
                seat.AddField("yaw", R(s.yawDeg)); seat.AddField("w", R(s.size.x)); seat.AddField("d", R(s.size.y));
                j.AddField("seat", seat);
                // Standing now: in the leg being played (the queue's now-playing
                // item) and not streamed in later in that leg. currentLeg −1 =
                // nothing of this playlist stands yet (a select, before play).
                j.AddField("standing", s.Standing && s.leg == currentLeg);
                j.AddField("loadAt", s.loadAt);
                if (s.unloadAt >= 0) j.AddField("unloadAt", s.unloadAt); else j.AddField("unloadAt", JSONObject.nullObject);
                j.AddField("streamed", s.streamed);
                var sw = new JSONObject(JSONObject.Type.Array); foreach (int k in s.sharesWith) sw.Add(k);
                j.AddField("sharesWith", sw);
                j.AddField("homeReturn", s.homeReturn);
                if (s.offRoute) j.AddField("offRoute", true);
            }
            return j;
        }

        internal static JSONObject LegJson(PlaylistPlannedLeg l)
        {
            var j = new JSONObject();
            j.AddField("leg", l.leg); j.AddField("id", l.id ?? ""); j.AddField("name", l.name ?? "");
            j.AddField("beat", l.beat ?? ""); j.AddField("minutes", R(l.minutes));
            if (!string.IsNullOrEmpty(l.contentId)) j.AddField("contentId", l.contentId);
            var ob = new JSONObject();
            ob.AddField("type", l.objectiveType ?? "");
            if (!string.IsNullOrEmpty(l.objectiveTarget)) ob.AddField("target", l.objectiveTarget);
            if (l.objectiveCount > 0) ob.AddField("count", l.objectiveCount);
            if (l.objectiveSeconds > 0) ob.AddField("seconds", R(l.objectiveSeconds));
            j.AddField("objective", ob);
            j.AddField("next", l.next ?? ""); j.AddField("nextApplied", l.nextApplied ?? "");
            j.AddField("degraded", l.degraded); j.AddField("titleSwitch", l.titleSwitch); j.AddField("walk", l.walk);
            j.AddField("rooms", Arr(l.rooms)); j.AddField("stops", Arr(l.stops));
            j.AddField("loadAtStart", Arr(l.loadAtStart)); j.AddField("unloadAtStart", Arr(l.unloadAtStart));
            var si = new JSONObject(JSONObject.Type.Array);
            foreach (var (order, after) in l.streamIn) { var x = new JSONObject(); x.AddField("order", order); x.AddField("after", after); si.Add(x); }
            j.AddField("streamIn", si);
            return j;
        }

        /// The leg a queue item names (`arrangement.legId`): its id, else
        /// "leg{n}" (1-based), else its 0-based index as text.
        public PlaylistPlannedLeg FindLeg(string legId)
        {
            if (string.IsNullOrEmpty(legId)) return null;
            foreach (var l in legs) if (string.Equals(l.id, legId, StringComparison.Ordinal)) return l;
            foreach (var l in legs) if (string.Equals("leg" + (l.leg + 1), legId, StringComparison.OrdinalIgnoreCase)) return l;
            if (int.TryParse(legId, NumberStyles.Integer, CultureInfo.InvariantCulture, out int i) && i >= 0 && i < legs.Count) return legs[i];
            return null;
        }

        public List<PlaylistPlacedStop> StopsOf(PlaylistPlannedLeg leg)
        {
            var list = new List<PlaylistPlacedStop>();
            if (leg != null) foreach (int o in leg.stops) list.Add(stops[o]);
            return list;
        }

        /// One leg of the plan — what a queue item packs — with where it sits in the arc.
        public JSONObject LegPlanJson(PlaylistPlannedLeg leg)
        {
            var o = new JSONObject();
            o.AddField("playlistId", playlistId ?? "");
            o.AddField("legId", leg?.id ?? "");
            o.AddField("legIndex", leg?.leg ?? -1);
            o.AddField("legCount", legs.Count);
            o.AddField("status", status);
            o.AddField("seed", seed); o.AddField("variant", variant);
            o.AddField("signature", Hash(signature));
            if (leg != null)
            {
                o.AddField("leg", LegJson(leg));
                var st = new JSONObject(JSONObject.Type.Array);
                foreach (var s in StopsOf(leg)) st.Add(StopJson(s, leg.leg));
                o.AddField("stops", st);
            }
            return o;
        }

        /// A short stable id of the whole plan (the phone checks every leg it
        /// packs came from the same plan).
        public static string Hash(string text)
        {
            unchecked
            {
                uint h = 2166136261;
                foreach (char c in text ?? "") { h ^= c; h *= 16777619; }
                return h.ToString("x8", CultureInfo.InvariantCulture);
            }
        }

        private static JSONObject Arr(List<int> xs) { var a = new JSONObject(JSONObject.Type.Array); foreach (int x in xs) a.Add(x); return a; }
        private static JSONObject Arr(List<string> xs) { var a = new JSONObject(JSONObject.Type.Array); foreach (string x in xs) a.Add(x); return a; }
        private static float R(float v) => (float)Math.Round(v, 3);

        /// Readable multi-line plan (tests, logs).
        public string Describe()
        {
            var sb = new StringBuilder();
            sb.AppendLine($"{name} [{playlistId}] status={status} fits={fits}{(fitReason != "" ? " (" + fitReason + ")" : "")} mode={layoutMode} variant={variant}/{variantCount} score={score:F1}");
            sb.Append("  route: ");
            for (int i = 0; i < route.Count; i++) sb.Append((i > 0 ? " → " : "") + route[i].name + (route[i].outdoor ? "*" : "") + $"({route[i].usableArea:F0}m²)");
            sb.AppendLine();
            foreach (var l in legs)
            {
                sb.AppendLine($"  leg {l.leg + 1} {l.beat,-8} \"{l.name}\" {l.minutes:0.#}min next={l.next}{(l.nextApplied != l.next ? "→" + l.nextApplied : "")}{(l.degraded ? " DEGRADED" : "")}{(l.titleSwitch ? " TITLE-SWITCH" : "")} walk={l.walk} rooms=[{string.Join(",", l.rooms)}]");
                foreach (int o in l.stops)
                {
                    var s = stops[o];
                    if (!s.placedOk) { sb.AppendLine($"     #{o + 1} {s.role,-8} {s.attraction} UNPLACED"); continue; }
                    sb.AppendLine($"     #{o + 1} {s.role,-8} {s.placed}{(s.variant != "primary" ? " (" + s.variant + " of " + s.attraction + ")" : "")} @ {s.roomName} {s.rectId} {s.size.x:F1}x{s.size.y:F1}m ({s.center.x:F1},{s.center.y:F1}) load@{s.loadAt}{(s.unloadAt >= 0 ? " unload@" + s.unloadAt : "")}{(s.streamed ? " STREAMED" : "")}{(s.homeReturn ? " HOME" : "")}{(s.offRoute ? " OFF-ROUTE" : "")}");
                }
            }
            sb.AppendLine("  summary: " + Summary());
            foreach (string n in notes) sb.AppendLine("  note: " + n);
            return sb.ToString();
        }
    }

    // ── Planner ──────────────────────────────────────────────────────────

    public static class PlaylistPacker
    {
        /// Gap kept between two stops standing at the same time (metres, total).
        public const float SeparationM = 0.3f;
        /// Legs this short (minutes) in a row are a gauntlet: one room, streamed in place.
        public const float GauntletLegMinutes = 2f;
        /// Diagnostics: every candidate plan's score (the offline harness sets it).
        public static Action<string> Trace;

        private sealed class Cand
        {
            public PlaylistItemRef item;
            public Vector2 size;
            public string kind;   // primary | alternate | shrink
        }

        private sealed class StopWork
        {
            public int order, leg, idx;
            public PlaylistStopSpec spec;
            public PlaylistLegSpec legSpec;
            public string contentId;
            public readonly List<Cand> cands = new List<Cand>();
            public Vector2 minSize;
        }

        private sealed class Item
        {
            public int order;
            public SpaceRect rect;
            public Vector2 lmin, lmax;   // rect-local box (inflated by half the separation)
            public int load;
        }

        public static PlaylistPlan Pack(PlaylistSpec spec, SpaceMapData map, PlaylistFootprintBook book, PlaylistPackOptions opt = null)
        {
            opt ??= new PlaylistPackOptions();
            var empty = new PlaylistPlan { playlistId = spec?.id, contentId = spec?.contentId, name = spec?.name, seed = opt.seed, variant = opt.variant };
            if (spec == null || spec.legs.Count == 0) { empty.fitReason = "playlist has no legs"; return empty; }
            PlaylistRoomGraph g = PlaylistRoomGraph.Build(map);
            empty.graph = g;
            if (g.nodes.Count == 0) { empty.fitReason = "no floor"; return empty; }

            // Flatten stops and their size ladders.
            var work = new List<StopWork>();
            for (int l = 0; l < spec.legs.Count; l++)
                for (int i = 0; i < spec.legs[l].stops.Count; i++)
                {
                    PlaylistLegSpec leg = spec.legs[l];
                    PlaylistStopSpec s = leg.stops[i];
                    var w = new StopWork { order = work.Count, leg = l, idx = i, spec = s, legSpec = leg,
                        contentId = s.contentId ?? leg.contentId ?? spec.contentId };
                    BuildCands(w, book);
                    work.Add(w);
                }

            // Fit filter (indoor / outdoor).
            int allowed = 0; float allowedArea = 0f;
            foreach (var n in g.nodes)
            {
                n.excluded = (n.outdoor && !spec.outdoor) || (!n.outdoor && !spec.indoor);
                if (!n.excluded) { allowed++; allowedArea += n.usableArea; }
            }
            if (allowed == 0)
            {
                empty.fitReason = spec.outdoor ? "needs outdoor space" : "needs indoor space";
                return empty;
            }

            int climaxLeg = ClimaxLeg(spec);
            int boss = BossOrder(work, climaxLeg);
            int start = g.entrance;
            if (g.nodes[start].excluded)
            {
                float best = float.MaxValue;
                foreach (var n in g.nodes) if (!n.excluded && Vector2.Distance(n.centroid, g.entrancePoint) < best) { best = Vector2.Distance(n.centroid, g.entrancePoint); start = n.index; }
            }

            // Candidate routes: simple paths from the entrance; cheap score; top K packed for real.
            var paths = new List<(List<int> path, float score, string sig)>();
            var stack = new List<int> { start };
            var onPath = new bool[g.nodes.Count]; onPath[start] = true;
            int count = 0;
            Enumerate(g, stack, onPath, ref count, opt.maxPaths, Math.Min(g.nodes.Count, 12), p =>
            {
                float s = CheapScore(spec, g, p, work, boss, climaxLeg);
                if (s > float.MinValue) paths.Add((new List<int>(p), s, Sig(p)));
                // A LOOP: out through the rooms and back to the entrance room for
                // the climax — for the common plan where you come in through the
                // biggest room (front door into the living room).
                if (p.Count >= 2)
                {
                    var loop = new List<int>(p) { p[0] };
                    float ls = CheapScore(spec, g, loop, work, boss, climaxLeg);
                    if (ls > float.MinValue) paths.Add((loop, ls, Sig(loop)));
                }
            });
            if (opt.legsMayRevisit)
                foreach (List<int> tour in Tours(g, start, work, boss))
                {
                    float ts = CheapScore(spec, g, tour, work, boss, climaxLeg);
                    string sig = Sig(tour);
                    if (ts > float.MinValue && !paths.Exists(x => x.sig == sig)) paths.Add((tour, ts, sig));
                }
            paths.Sort((a, b) => { int c = b.score.CompareTo(a.score); return c != 0 ? c : string.CompareOrdinal(a.sig, b.sig); });
            if (paths.Count == 0) paths.Add((new List<int> { start }, 0f, Sig(new List<int> { start })));

            var plans = new List<PlaylistPlan>();
            for (int i = 0; i < paths.Count && i < opt.simulateTop; i++)
            {
                PlaylistPlan p = Simulate(spec, g, map, paths[i].path, work, boss, climaxLeg);
                Trace?.Invoke($"  [route] cheap {paths[i].score,7:F1} + packed {p.score,7:F1}  {paths[i].sig}");
                p.score += paths[i].score;
                plans.Add(p);
            }
            plans.Sort((a, b) => { int c = b.score.CompareTo(a.score); return c != 0 ? c : string.CompareOrdinal(a.signature, b.signature); });
            if (Trace != null)
                foreach (var p in plans)
                    Trace($"  [plan] {p.score,7:F1} route {string.Join(">", p.route.ConvertAll(n => n.name))} backtracks={p.backtracks}\n" + p.Describe());
            var distinct = new List<PlaylistPlan>();
            var seen = new HashSet<string>(StringComparer.Ordinal);
            foreach (var p in plans) if (seen.Add(p.signature)) distinct.Add(p);

            // "Different adventure" only ever offers GOOD plans: within a margin
            // of the best, and with the climax in the same kind of space.
            float margin = Mathf.Max(15f, Mathf.Abs(distinct[0].score) * 0.15f);
            bool bestOutdoor = ClimaxOutdoor(distinct[0], g);
            var good = new List<PlaylistPlan>();
            foreach (var p in distinct)
                if (good.Count < 6 && p.score >= distinct[0].score - margin && ClimaxOutdoor(p, g) == bestOutdoor) good.Add(p);
            PlaylistPlan chosen = good[0];
            if (opt.variant > 0) chosen = good[opt.variant % good.Count];
            else if (opt.seed != 0) chosen = good[new System.Random(opt.seed).Next(good.Count)];
            chosen.seed = opt.seed;
            chosen.variant = opt.variant;
            chosen.variantCount = good.Count;

            // Fit hints (the plan is still made, so the phone can say why).
            int usableRooms = 0;
            foreach (var n in g.nodes) if (!n.excluded && n.usableArea >= 4f) usableRooms++;
            var reasons = new List<string>();
            if (spec.minRooms > 1 && usableRooms < spec.minRooms) reasons.Add($"needs {spec.minRooms} rooms, space has {usableRooms}");
            if (spec.minAreaM2 > 0f && allowedArea < spec.minAreaM2) reasons.Add($"needs {spec.minAreaM2:0} m², space has {allowedArea:0}");
            bool requiredMissing = false, anyMissing = false;
            foreach (var s in chosen.stops)
                if (!s.placedOk) { anyMissing = true; if (s.role != "stage") requiredMissing = true; }
            if (requiredMissing) reasons.Add("a start/boss/end stop does not fit anywhere");
            chosen.fits = reasons.Count == 0;
            chosen.fitReason = string.Join("; ", reasons);
            chosen.status = !chosen.fits ? "no-fit" : anyMissing ? "partial" : "ready";
            return chosen;
        }

        private static bool ClimaxOutdoor(PlaylistPlan p, PlaylistRoomGraph g)
        {
            foreach (var n in g.nodes) if (n.roomId == p.climaxRoomId) return n.outdoor;
            return false;
        }

        /// "planFor(playlist, legId)": the whole arc is planned (deterministic,
        /// seeded) and the one leg a queue item names is returned with it, so
        /// every leg's pack agrees with the arc — start at the entrance, the
        /// boss in the dramatic space, later legs reusing rooms. Null leg = the
        /// id names no leg of this playlist.
        public static PlaylistPlan PlanFor(PlaylistSpec spec, string legId, SpaceMapData map, PlaylistFootprintBook book,
            PlaylistPackOptions opt, out PlaylistPlannedLeg leg)
        {
            PlaylistPlan plan = Pack(spec, map, book, opt);
            leg = plan.FindLeg(legId);
            return plan;
        }

        // ── stop ladders ──

        private static void BuildCands(StopWork w, PlaylistFootprintBook book)
        {
            // Each attraction's ladder: authored first, then its smaller layout sizes.
            List<Vector2> Ladder(PlaylistItemRef r, bool primary)
            {
                if (primary && w.spec.footprintM != Vector2.zero)
                    return w.spec.minFootprintM != Vector2.zero
                        ? new List<Vector2> { w.spec.footprintM, w.spec.minFootprintM } : new List<Vector2> { w.spec.footprintM };
                if (book != null && book.TryGet(w.contentId, r, out var e) && e.ladder != null) return e.ladder;
                return new List<Vector2> { PlaylistFootprintBook.DefaultAuthored, PlaylistFootprintBook.DefaultMinimum };
            }
            // Order: the attraction as authored, each alternate as authored, then
            // the smaller layout sizes of the attraction, then of each alternate.
            var ladders = new List<(PlaylistItemRef item, List<Vector2> sizes)> { (w.spec.item, Ladder(w.spec.item, true)) };
            foreach (var alt in w.spec.alternates) ladders.Add((alt, Ladder(alt, false)));
            w.cands.Add(new Cand { item = w.spec.item, size = ladders[0].sizes[0], kind = "primary" });
            for (int i = 1; i < ladders.Count; i++) w.cands.Add(new Cand { item = ladders[i].item, size = ladders[i].sizes[0], kind = "alternate" });
            foreach (var (item, sizes) in ladders)
                for (int i = 1; i < sizes.Count; i++)
                {
                    bool dup = false;
                    foreach (var c in w.cands) if (c.item == item && Approximately(c.size, sizes[i])) dup = true;
                    if (!dup) w.cands.Add(new Cand { item = item, size = sizes[i], kind = "shrink" });
                }
            w.minSize = w.cands[0].size;
            foreach (var c in w.cands) if (c.size.x * c.size.y < w.minSize.x * w.minSize.y) w.minSize = c.size;
        }

        private static bool Approximately(Vector2 a, Vector2 b) => Mathf.Abs(a.x - b.x) < 0.01f && Mathf.Abs(a.y - b.y) < 0.01f;

        private static int ClimaxLeg(PlaylistSpec spec)
        {
            for (int i = 0; i < spec.legs.Count; i++) if (spec.legs[i].beat == "climax") return i;
            for (int i = 0; i < spec.legs.Count; i++) foreach (var s in spec.legs[i].stops) if (s.role == "boss") return i;
            for (int i = spec.legs.Count - 1; i >= 0; i--) if (spec.legs[i].beat != "finale") return i;
            return spec.legs.Count - 1;
        }

        private static int BossOrder(List<StopWork> work, int climaxLeg)
        {
            int last = -1, mini = -1;
            foreach (var w in work)
            {
                if (w.leg != climaxLeg) continue;
                if (w.spec.role == "boss") return w.order;
                if (w.spec.role == "miniboss") mini = w.order;
                last = w.order;
            }
            return mini >= 0 ? mini : last;
        }

        // ── routes ──

        private static void Enumerate(PlaylistRoomGraph g, List<int> stack, bool[] onPath, ref int count, int max, int depth, Action<List<int>> visit)
        {
            if (count >= max) return;
            count++;
            visit(stack);
            if (stack.Count >= depth) return;
            int u = stack[stack.Count - 1];
            var next = new List<PlaylistRoomEdge>(g.adj[u]);
            next.Sort((a, b) => { int c = a.cost.CompareTo(b.cost); return c != 0 ? c : a.Other(u).CompareTo(b.Other(u)); });
            foreach (var e in next)
            {
                int v = e.Other(u);
                if (onPath[v] || g.nodes[v].excluded) continue;
                onPath[v] = true; stack.Add(v);
                Enumerate(g, stack, onPath, ref count, max, depth, visit);
                stack.RemoveAt(stack.Count - 1); onPath[v] = false;
                if (count >= max) return;
            }
        }

        private static string Sig(List<int> p) => string.Join(">", p);

        /// TOURS (legsMayRevisit): host rooms in the order a walk from the entrance
        /// visits them when every dead-end wing is done before the trunk carries on
        /// to the climax room — the shortest-path tree, side branches first
        /// (nearest first), the climax room last. Each candidate climax room gives
        /// tours with its first 1..W side wings; a leg may only start in a wing.
        private static List<List<int>> Tours(PlaylistRoomGraph g, int start, List<StopWork> work, int boss)
        {
            var tours = new List<List<int>>();
            int n = g.nodes.Count;
            if (n < 3 || boss < 0) return tours;
            // Shortest-path tree from the entrance.
            var parent = new int[n];
            for (int v = 0; v < n; v++)
            {
                parent[v] = -1;
                if (v == start || g.nodes[v].excluded || float.IsInfinity(g.Dist(start, v))) continue;
                List<int> w = g.Walk(start, v);
                parent[v] = w.Count >= 2 ? w[w.Count - 2] : -1;
            }
            var children = new List<List<int>>();
            for (int v = 0; v < n; v++) children.Add(new List<int>());
            for (int v = 0; v < n; v++) if (parent[v] >= 0) children[parent[v]].Add(v);
            foreach (var c in children) c.Sort((a, b) => { int x = g.Dist(start, a).CompareTo(g.Dist(start, b)); return x != 0 ? x : a.CompareTo(b); });
            // Climax candidates: the best few rooms the boss fits, by its preference.
            var climax = new List<int>();
            for (int v = 0; v < n; v++) if (v != start && !g.nodes[v].excluded && parent[v] >= 0 && BossFits(g.nodes[v], work[boss])) climax.Add(v);
            climax.Sort((a, b) => BossValue(g, g.nodes[b], work[boss].spec.prefer).CompareTo(BossValue(g, g.nodes[a], work[boss].spec.prefer)));
            if (climax.Count > 3) climax.RemoveRange(3, climax.Count - 3);
            foreach (int c in climax)
            {
                var trunk = new HashSet<int>();
                for (int v = c; v >= 0; v = parent[v]) trunk.Add(v);
                // Side wings hanging off the trunk (before the climax room), as subtree preorders.
                var wings = new List<(int anchor, List<int> rooms)>();
                foreach (int t in trunk)
                {
                    if (t == c) continue;
                    foreach (int ch in children[t])
                    {
                        if (trunk.Contains(ch)) continue;
                        var wing = new List<int>();
                        var stack = new Stack<int>(); stack.Push(ch);
                        while (stack.Count > 0)
                        {
                            int u = stack.Pop();
                            if (g.nodes[u].excluded) continue;
                            if (HostsStops(g.nodes[u], work, boss)) wing.Add(u);
                            for (int i = children[u].Count - 1; i >= 0; i--) stack.Push(children[u][i]);
                        }
                        if (wing.Count > 0) wings.Add((t, wing));
                    }
                }
                if (wings.Count == 0) continue;
                wings.Sort((a, b) => { int x = g.Dist(start, a.rooms[0]).CompareTo(g.Dist(start, b.rooms[0])); return x != 0 ? x : a.rooms[0].CompareTo(b.rooms[0]); });
                // Trunk order from the entrance; each wing goes in right after the trunk room it hangs off.
                var trunkOrder = new List<int>();
                for (int v = c; v >= 0; v = parent[v]) trunkOrder.Insert(0, v);
                for (int take = 1; take <= wings.Count; take++)
                {
                    var tour = new List<int>();
                    var used = new HashSet<int>();
                    foreach (int t in trunkOrder)
                    {
                        if (t != c && (t == start || HostsStops(g.nodes[t], work, boss)) && used.Add(t)) tour.Add(t);
                        if (t == c) break;
                        for (int wi = 0; wi < take; wi++)
                            if (wings[wi].anchor == t)
                                foreach (int u in wings[wi].rooms) if (used.Add(u)) tour.Add(u);
                    }
                    if (tour.Count == 0 || tour[0] != start) tour.Insert(0, start);
                    tour.Add(c);
                    tours.Add(tour);
                }
            }
            return tours;
        }

        internal static bool FitsRoom(PlaylistRoomNode n, Vector2 size)
        {
            foreach (SpaceRect r in n.rects)
                if ((size.x <= r.w + 1e-3f && size.y <= r.d + 1e-3f) || (size.y <= r.w + 1e-3f && size.x <= r.d + 1e-3f)) return true;
            return false;
        }

        private static bool BossFits(PlaylistRoomNode n, StopWork boss)
        {
            foreach (var c in boss.cands) if (FitsRoom(n, c.size)) return true;
            return false;
        }

        internal static float BossValue(PlaylistRoomGraph g, PlaylistRoomNode n, string prefer)
        {
            switch (prefer)
            {
                // No outdoor space: the most dramatic indoor one.
                case "outdoor": return (n.outdoor ? 60f : 0f) + n.drama;
                case "far": return n.walkM * 2f + n.hops * 6f + n.largestRectArea * 0.2f;
                case "entrance": return -n.walkM * 2f - n.hops * 6f;
                default: return n.drama;
            }
        }

        private static List<List<int>> PreSets(PlaylistSpec spec, int climaxLeg)
        {
            var sets = new List<List<int>>();
            for (int l = 0; l < climaxLeg; l++)
            {
                bool join = l > 0 && (spec.legs[l - 1].next == "swap_in_place" || Gauntlet(spec, l - 1, l));
                if (!join) sets.Add(new List<int>());
                sets[sets.Count - 1].Add(l);
            }
            return sets;
        }

        /// Two quick legs in a row stream in place in one room. A BOOKEND leg (Start Lobby / Results Room,
        /// § 11) is never part of a gauntlet: it stands in its own room-set (the lobby at the door).
        private static bool Gauntlet(PlaylistSpec spec, int a, int b) =>
            spec.legs[a].minutes > 0f && spec.legs[a].minutes <= GauntletLegMinutes
            && spec.legs[b].minutes > 0f && spec.legs[b].minutes <= GauntletLegMinutes
            && !IsBookendLeg(spec.legs[a]) && !IsBookendLeg(spec.legs[b]);

        public static bool IsBookendLeg(PlaylistLegSpec leg)
        {
            if (leg?.stops == null || leg.stops.Count == 0) return false;
            foreach (PlaylistStopSpec s in leg.stops)
                if (!PlaylistBookends.IsPlatformStop(s.contentId, s.item.Id)) return false;
            return true;
        }

        private static float CheapScore(PlaylistSpec spec, PlaylistRoomGraph g, List<int> p, List<StopWork> work, int boss, int climaxLeg)
        {
            PlaylistRoomNode end = g.nodes[p[p.Count - 1]];
            if (boss < 0 || !BossFits(end, work[boss])) return float.MinValue;
            int m = 0;
            foreach (var w in work) if (w.order < boss) m++;
            int k = p.Count - 1, u = 0;
            bool loop = k > 0 && p[k] == p[0];
            for (int i = 0; i < k; i++) if (HostsStops(g.nodes[p[i]], work, boss)) u++;
            int sets = Math.Max(1, PreSets(spec, climaxLeg).Count);
            float walk = 0f;
            int last = loop ? k - 1 : k;
            for (int i = 1; i <= last; i++) walk += g.Dist(p[i - 1], p[i]);
            if (loop) walk *= 2f;   // out and back
            float s = 10f * Math.Min(u, sets) + 3f * Math.Min(u, m) - 5f * Math.Max(0, u - m) - 2f * (k - u) - 0.2f * walk;
            // The climax in the most dramatic space outweighs touring one more room.
            s += 1.5f * BossValue(g, end, work[boss].spec.prefer);
            if (loop) s -= 6f;
            int usableAllowed = 0;
            foreach (var n in g.nodes) if (!n.excluded && HostsStops(n, work, boss)) usableAllowed++;
            if (k == 0 && usableAllowed >= 2 && m > 0) s -= 20f;
            return s;
        }

        /// A room that can take at least half of the stops before the climax
        /// (some size of each) — smaller rooms are walked through, not played in.
        private static bool HostsStops(PlaylistRoomNode n, List<StopWork> work, int boss)
        {
            int m = 0, fit = 0;
            foreach (var w in work)
            {
                if (w.order >= boss) continue;
                m++;
                foreach (var c in w.cands) if (FitsRoom(n, c.size)) { fit++; break; }
            }
            return m > 0 && fit * 2 >= m;
        }

        // ── one full plan over one route ──

        private static PlaylistPlan Simulate(PlaylistSpec spec, PlaylistRoomGraph g, SpaceMapData map, List<int> path,
            List<StopWork> work, int boss, int climaxLeg)
        {
            var plan = new PlaylistPlan { playlistId = spec.id, contentId = spec.contentId, name = spec.name, graph = g,
                entranceRoomId = g.nodes[path[0]].roomId, entrancePoint = g.entrancePoint, climaxOrder = boss };
            int k = path.Count - 1;
            bool loop = k > 0 && path[k] == path[0];
            foreach (int i in path) plan.route.Add(g.nodes[i]);
            plan.climaxRoomId = g.nodes[path[k]].roomId;

            // Finale room: home (entrance), far (a neighbour of the climax room off the route), or stay.
            string finaleMode = "stay";
            foreach (var w in work) if (w.order > boss && w.leg != climaxLeg)
                { if (w.spec.prefer == "entrance") finaleMode = "home"; else if (w.spec.prefer == "far" && finaleMode == "stay") finaleMode = "far"; }
            int farRoom = -1;
            if (finaleMode == "far")
            {
                float best = float.MinValue;
                foreach (var e in g.adj[path[k]])
                {
                    int v = e.Other(path[k]);
                    if (path.Contains(v) || g.nodes[v].excluded) continue;
                    if (g.nodes[v].usableArea > best) { best = g.nodes[v].usableArea; farRoom = v; }
                }
                if (farRoom < 0) finaleMode = "stay";
                else plan.route.Add(g.nodes[farRoom]);
            }
            if (finaleMode == "home" && (k == 0 || loop)) finaleMode = "stay";

            // Room-sets of the pre-climax legs → blocks of route rooms.
            List<List<int>> sets = PreSets(spec, climaxLeg);
            var preRooms = new List<int>();
            for (int i = 0; i < k; i++) if (HostsStops(g.nodes[path[i]], work, boss)) preRooms.Add(i);
            var legRooms = new List<List<int>>();   // per leg: route indices in walking order
            for (int l = 0; l < spec.legs.Count; l++) legRooms.Add(new List<int>());
            if (sets.Count > 0)
            {
                if (preRooms.Count == 0)
                {
                    foreach (var set in sets) foreach (int l in set) legRooms[l].Add(k);
                }
                else if (preRooms.Count >= sets.Count)
                {
                    var need = new List<int>();
                    foreach (var set in sets) { int mx = 1; foreach (int l in set) mx = Math.Max(mx, spec.legs[l].stops.Count); need.Add(mx); }
                    List<int> sizes = Allocate(need, preRooms.Count);
                    // Never more rooms than the set has stops in a leg: a quick
                    // gauntlet stays in one room, streamed in place.
                    for (int si = 0; si < sizes.Count; si++) sizes[si] = Math.Min(sizes[si], need[si]);
                    int at = 0;
                    for (int si = 0; si < sets.Count; si++)
                    {
                        var block = preRooms.GetRange(at, sizes[si]);
                        at += sizes[si];
                        // WITHIN a leg the walk never re-enters a room it left: a block
                        // ends where the walk to its next room would (a tour's wing).
                        var visited = new HashSet<int> { path[block[0]] };
                        for (int b = 1; b < block.Count; b++)
                        {
                            List<int> walk = g.Walk(path[block[b - 1]], path[block[b]]);
                            bool reenters = false;
                            for (int q = 1; q < walk.Count; q++) if (visited.Contains(walk[q])) reenters = true;
                            if (reenters) { block.RemoveRange(b, block.Count - b); break; }
                            foreach (int q in walk) visited.Add(q);
                        }
                        for (int li = 0; li < sets[si].Count; li++)
                        {
                            var order = new List<int>(block);
                            if (li % 2 == 1) order.Reverse();   // "back through the same rooms"
                            legRooms[sets[si][li]].AddRange(order);
                        }
                    }
                }
                else
                {
                    for (int si = 0; si < sets.Count; si++)
                    {
                        int room = preRooms[si * preRooms.Count / sets.Count];
                        foreach (int l in sets[si]) legRooms[l].Add(room);
                    }
                }
            }
            // The climax leg plays in the climax room; with no earlier legs its
            // approach stops walk the route to it.
            if (sets.Count == 0) { legRooms[climaxLeg].AddRange(preRooms); }
            legRooms[climaxLeg].Add(k);
            int finaleRouteIdx = finaleMode == "home" ? 0 : finaleMode == "far" ? k + 1 : k;
            for (int l = climaxLeg + 1; l < spec.legs.Count; l++) legRooms[l].Add(finaleRouteIdx);

            // Leg transitions actually applied.
            var nextApplied = new string[spec.legs.Count];
            var chainStart = new int[spec.legs.Count];
            var firstOrder = new int[spec.legs.Count];
            for (int l = 0, o = 0; l < spec.legs.Count; l++) { firstOrder[l] = o; o += spec.legs[l].stops.Count; }
            for (int l = 0; l < spec.legs.Count; l++)
            {
                var pl = new PlaylistPlannedLeg
                {
                    leg = l, id = spec.legs[l].id, name = spec.legs[l].name, beat = spec.legs[l].beat, next = spec.legs[l].next,
                    minutes = spec.legs[l].minutes, objectiveType = spec.legs[l].objectiveType, objectiveTarget = spec.legs[l].objectiveTarget,
                    objectiveCount = spec.legs[l].objectiveCount, objectiveSeconds = spec.legs[l].objectiveSeconds,
                    contentId = LegContent(spec, work, l),
                };
                nextApplied[l] = spec.legs[l].next;
                if (l + 1 < spec.legs.Count && spec.legs[l].next == "walk_on")
                {
                    bool same = legRooms[l + 1].Count > 0;
                    foreach (int r in legRooms[l + 1]) if (!legRooms[l].Contains(r)) same = false;
                    if (same && l + 1 <= climaxLeg)
                    {
                        nextApplied[l] = "swap_in_place";
                        pl.degraded = !Gauntlet(spec, l, l + 1);
                        plan.notes.Add(Gauntlet(spec, l, l + 1)
                            ? $"legs {l + 1}–{l + 2} are a quick gauntlet: streamed in place"
                            : $"leg {l + 1} → {l + 2}: walk_on became swap_in_place (not enough rooms)");
                    }
                }
                if (l == spec.legs.Count - 1) nextApplied[l] = "";
                pl.nextApplied = nextApplied[l];
                pl.titleSwitch = l > 0 && !string.Equals(LegContent(spec, work, l), LegContent(spec, work, l - 1), StringComparison.Ordinal);
                // ONE LEG AT A TIME (Aidan, Oct 18: a playlist is a program for the
                // GameMaster queue — each leg is one queue item, nothing runs two
                // games at once): a leg's stops load when it starts and the whole
                // leg goes when the next one starts, so a later leg may reuse any
                // floor an earlier one stood on.
                chainStart[l] = firstOrder[l];
                plan.legs.Add(pl);
            }

            // Entry / exit points per route room.
            Vector2 Door(int i, int j)
            {
                if (loop && j == k && i == k - 1) { i = 0; j = 1; }   // back into the entrance room
                int a = i < path.Count ? path[i] : farRoom, b = j < path.Count ? path[j] : farRoom;
                var e = g.Edge(a, b);
                return e != null ? e.door : (g.nodes[a].centroid + g.nodes[b].centroid) * 0.5f;
            }
            int NodeAt(int routeIdx) => routeIdx < path.Count ? path[routeIdx] : farRoom;
            Vector2 Entry(int ri) => ri == 0 ? g.entrancePoint : Door(ri - 1, ri);
            Vector2 Exit(int ri) => ri < k ? Door(ri, ri + 1) : FarPoint(g.nodes[NodeAt(ri)], Entry(ri));

            // Reserve the climax spot first: far side of the climax room, its best size.
            var items = new List<Item>();
            Item reservation = null;
            {
                PlaylistRoomNode bn = g.nodes[path[k]];
                Vector2 target = Exit(k);
                foreach (var c in work[boss].cands)
                    if (TryPosition(bn, c.size, target, items, null, -1, int.MaxValue, false, out Item it)) { reservation = it; break; }
            }

            // The arc's PROGRESS through each room across every leg that plays
            // forward in it: a room that hosts several legs (one open party room,
            // a park) is crossed once, from where you come in to the climax end,
            // instead of restarting at the door every leg.
            var preRoute = new int[work.Count];
            var preForward = new bool[work.Count];
            for (int l = 0; l < spec.legs.Count; l++)
            {
                List<int> rooms = legRooms[l];
                var legStops = work.FindAll(w => w.leg == l);
                bool legBack = rooms.Count >= 2 && rooms[0] > rooms[rooms.Count - 1];
                bool legHome = l > climaxLeg && finaleMode == "home";
                for (int j = 0; j < legStops.Count; j++)
                {
                    int r = rooms.Count == 0 ? k : rooms[Math.Min(rooms.Count - 1, j * rooms.Count / legStops.Count)];
                    if (l == climaxLeg && legStops[j].order >= boss) r = k;
                    preRoute[legStops[j].order] = r;
                    preForward[legStops[j].order] = !legBack && !legHome;
                }
            }
            int ProgressRank(int order, out int total)
            {
                int rank = 0; total = 0;
                for (int o = 0; o < work.Count; o++)
                {
                    if (!preForward[o] || preRoute[o] != preRoute[order]) continue;
                    total++;
                    if (o < order) rank++;
                }
                return rank;
            }

            Vector2 prevPoint = g.entrancePoint;
            int lastRoute = 0, lastLeg = -1;
            for (int l = 0; l < spec.legs.Count; l++)
            {
                List<int> rooms = legRooms[l];
                var stopsOfLeg = work.FindAll(w => w.leg == l);
                int n = stopsOfLeg.Count;
                bool back = false;
                if (rooms.Count >= 2 && rooms[0] > rooms[rooms.Count - 1]) back = true;
                // Distribute the leg's stops over its rooms in walking order.
                var assigned = new int[n];
                for (int j = 0; j < n; j++) assigned[j] = rooms.Count == 0 ? k : rooms[Math.Min(rooms.Count - 1, j * rooms.Count / n)];
                if (l == climaxLeg)
                    for (int j = 0; j < n; j++) if (stopsOfLeg[j].order >= boss) assigned[j] = k;
                // THE START IS AT THE DOOR: the arc's first stop (and an opening stop that asks for the
                // entrance / the players) plays in the entrance room whenever any of its sizes fits there —
                // standing or streamed — even when the leg's other stops only fit further on.
                if (l <= climaxLeg)
                    for (int j = 0; j < n; j++)
                    {
                        StopWork sw = stopsOfLeg[j];
                        bool wantsDoor = sw.order == 0 || (spec.legs[l].beat == "opening"
                            && (sw.spec.prefer == "entrance" || sw.spec.prefer == "players"));
                        if (!wantsDoor || sw.order >= boss) continue;   // the climax keeps the dramatic space
                        foreach (var c in sw.cands)
                            if (FitsRoom(g.nodes[path[0]], c.size)) { assigned[j] = 0; break; }
                    }
                // Same walk as the stop before (this leg, or a walk_on from the
                // last): never send the player back to a room already left.
                // Across legs too (each its own queue item): once the arc has moved on — say the opening only
                // fit outdoors — a later forward leg does not go back to an earlier room on the route. The
                // route's order already holds any planned wing (tours), so this never undoes a revisit tour.
                bool sameWalk = !back && lastLeg >= 0 && l <= climaxLeg;
                for (int j = 0; j < n; j++)
                {
                    StopWork w = stopsOfLeg[j];
                    if ((sameWalk || j > 0) && !back && assigned[j] < lastRoute && assigned[j] <= k && lastRoute <= k) assigned[j] = lastRoute;
                    int ri = assigned[j];
                    int sameRoomBefore = 0, sameRoomTotal = 0;
                    for (int q = 0; q < n; q++) if (assigned[q] == ri) { sameRoomTotal++; if (q < j) sameRoomBefore++; }
                    Vector2 entry = Entry(Math.Min(ri, k)), exit = Exit(Math.Min(ri, k));
                    if (ri > k) { entry = Door(k, k + 1); exit = FarPoint(g.nodes[farRoom], entry); }
                    if (back) { var t = entry; entry = exit; exit = t; }
                    bool home = l > climaxLeg && finaleMode == "home";
                    if (home) { entry = k > 0 ? Door(0, 1) : entry; exit = g.entrancePoint; }
                    float frac = (sameRoomBefore + 1f) / (sameRoomTotal + 1f);
                    if (!back && !home && preForward[w.order] && preRoute[w.order] == ri)
                    {
                        int rank = ProgressRank(w.order, out int total);
                        frac = (rank + 1f) / (total + 1f);
                    }
                    Vector2 target = w.order == boss && reservation != null ? Center(reservation) : Vector2.Lerp(entry, exit, frac);
                    if (w.spec.prefer == "entrance" && ri == 0) target = g.entrancePoint;

                    // One leg at a time: only the climax leg's own earlier stops could
                    // still stand when the boss loads, so only they keep off its spot.
                    Item keepOff = w.order != boss && l == climaxLeg ? reservation : null;
                    var placed = Place(g, path, k, farRoom, legRooms[l], ri, w, target, items, keepOff,
                        chainStart[l], w.order == boss ? reservation : null, out Item item, out Cand cand, out int roomNode, out bool offRoute);
                    var ps = new PlaylistPlacedStop
                    {
                        order = w.order, leg = l, indexInLeg = w.idx, role = w.spec.role, beat = spec.legs[l].beat, legId = spec.legs[l].id, legName = spec.legs[l].name,
                        contentId = w.contentId, prefer = w.spec.prefer, attraction = w.spec.item.Id, options = w.spec.options,
                        challenge = w.spec.challenge, introHint = w.spec.introHint, authoredAttractionId = w.spec.attractionId,
                        bonus = new List<string>(w.spec.bonus),
                        occurrenceId = $"pl-{spec.id}-{l}-{w.idx}",
                    };
                    if (placed)
                    {
                        PlaylistRoomNode rn = g.nodes[roomNode];
                        ps.placedOk = true;
                        ps.placed = cand.item.Id;
                        ps.resourceAddress = cand.item.resourceAddress;
                        ps.manifestOccurrenceId = cand.item.occurrenceId;
                        ps.variant = cand.kind;
                        ps.roomIndex = roomNode; ps.roomId = rn.roomId; ps.roomName = rn.name; ps.roomLabel = rn.label; ps.storyId = rn.storyId;
                        ps.routeIndex = RouteIndexOf(path, farRoom, roomNode, ri);
                        lastRoute = ps.routeIndex; lastLeg = l;
                        ps.offRoute = offRoute;
                        ps.rect = item.rect; ps.rectId = item.rect.rectId;
                        ps.local = Center(item);
                        ps.center = item.rect.RectToPark(ps.local);
                        ps.size = (item.lmax - item.lmin) - Vector2.one * SeparationM;
                        ps.yawDeg = item.rect.yawDeg;
                        ps.y = item.rect.FloorAt(ps.center);
                        ps.loadAt = item.load;
                        ps.streamed = item.load > chainStart[l];
                        ps.homeReturn = home && ri == 0;
                        ps.face = prevPoint;
                        prevPoint = ps.center;
                        if (cand.kind != "primary")
                            plan.notes.Add($"{ps.attraction}: {cand.kind} {ps.placed} {cand.size.x:F1}×{cand.size.y:F1} m (authored {w.cands[0].size.x:F1}×{w.cands[0].size.y:F1} m does not fit {rn.name})");
                        if (offRoute) plan.notes.Add($"{ps.attraction}: no floor on its route room, placed in the {rn.name}");
                        items.Add(item);
                    }
                    else
                    {
                        ps.placed = w.spec.item.Id;
                        plan.notes.Add($"{ps.attraction}: no floor anywhere (smallest {w.minSize.x:F1}×{w.minSize.y:F1} m)");
                    }
                    plan.stops.Add(ps);
                }
            }

            Finish(plan, spec, firstOrder, nextApplied, items);
            Score(plan, g, path, boss, work);
            return plan;
        }

        /// The route position of a room (a loop route has the entrance twice):
        /// the one nearest the position the stop was assigned, later on ties.
        private static int RouteIndexOf(List<int> path, int farRoom, int node, int assigned)
        {
            if (node == farRoom && farRoom >= 0) return path.Count;
            int best = -1;
            for (int i = 0; i < path.Count; i++)
                if (path[i] == node && (best < 0 || Math.Abs(i - assigned) <= Math.Abs(best - assigned))) best = i;
            return best;
        }

        private static string LegContent(PlaylistSpec spec, List<StopWork> work, int l)
        {
            // Platform bookend stops (PLAYLISTS.md § 11.2) never name the leg's game: a bookend leg
            // plays its neighbouring title (no title switch).
            foreach (var w in work)
                if (w.leg == l && !string.IsNullOrEmpty(w.contentId) && !PlaylistBookends.IsPlatformContent(w.contentId)) return w.contentId;
            string declared = spec.legs[l].contentId;
            if (!string.IsNullOrEmpty(declared) && !PlaylistBookends.IsPlatformContent(declared)) return declared;
            for (int d = 1; d < spec.legs.Count; d++)
                foreach (int n in new[] { l - d, l + d })
                {
                    if (n < 0 || n >= spec.legs.Count) continue;
                    foreach (var w in work)
                        if (w.leg == n && !string.IsNullOrEmpty(w.contentId) && !PlaylistBookends.IsPlatformContent(w.contentId)) return w.contentId;
                    string c = spec.legs[n].contentId;
                    if (!string.IsNullOrEmpty(c) && !PlaylistBookends.IsPlatformContent(c)) return c;
                }
            return spec.contentId ?? "";
        }

        private static List<int> Allocate(List<int> need, int total)
        {
            var sizes = new List<int>();
            int sum = 0; foreach (int x in need) sum += x;
            int left = total - need.Count;   // each gets 1
            var rema = new List<(float r, int i)>();
            for (int i = 0; i < need.Count; i++)
            {
                float exact = left * (need[i] / (float)Math.Max(1, sum));
                int f = (int)Math.Floor(exact);
                sizes.Add(1 + f);
                rema.Add((exact - f, i));
            }
            int given = 0; foreach (int s in sizes) given += s;
            rema.Sort((a, b) => { int c = b.r.CompareTo(a.r); return c != 0 ? c : a.i.CompareTo(b.i); });
            for (int q = 0; given < total && q < rema.Count; q++, given++) sizes[rema[q].i]++;
            return sizes;
        }

        private static Vector2 FarPoint(PlaylistRoomNode n, Vector2 from)
        {
            Vector2 best = n.centroid; float bd = -1f;
            foreach (SpaceRect r in n.rects)
            {
                Vector2 c = r.Center;
                for (int i = 0; i < 4; i++)
                {
                    Vector2 p = Vector2.Lerp(r.Corner(i), c, 0.35f);
                    float d = Vector2.Distance(p, from);
                    if (d > bd + 1e-4f) { bd = d; best = p; }
                }
            }
            return best;
        }

        private static Vector2 Center(Item it) => (it.lmin + it.lmax) * 0.5f;

        /// Tries the stop in its room (every size, free then streamed), then the
        /// leg's other rooms, the rest of the route, then anywhere allowed.
        private static bool Place(PlaylistRoomGraph g, List<int> path, int k, int farRoom, List<int> legRoute, int ri, StopWork w,
            Vector2 target, List<Item> items, Item avoid, int chainStart, Item preferSpot,
            out Item item, out Cand cand, out int roomNode, out bool offRoute)
        {
            var tryRooms = new List<int>();
            void add(int node) { if (node >= 0 && !tryRooms.Contains(node) && !g.nodes[node].excluded) tryRooms.Add(node); }
            int NodeAt(int idx) => idx < path.Count ? path[idx] : farRoom;
            // Its room; the leg's later rooms; the route onward (the climax room
            // last, so an early stop never spoils it); then back; then anywhere.
            add(NodeAt(ri));
            int at = legRoute.IndexOf(ri);
            for (int i = at + 1; at >= 0 && i < legRoute.Count; i++) add(NodeAt(legRoute[i]));
            for (int i = ri + 1; i < k; i++) add(path[i]);
            for (int i = Math.Min(ri, path.Count) - 1; i >= 0; i--) add(path[i]);
            add(path[k]);
            int onRoute = tryRooms.Count;
            var rest = new List<PlaylistRoomNode>();
            foreach (var n in g.nodes) if (!tryRooms.Contains(n.index) && !n.excluded) rest.Add(n);
            rest.Sort((a, b) => { int c = Vector2.Distance(a.centroid, target).CompareTo(Vector2.Distance(b.centroid, target)); return c != 0 ? c : a.index.CompareTo(b.index); });
            foreach (var n in rest) add(n.index);

            for (int t = 0; t < tryRooms.Count; t++)
            {
                PlaylistRoomNode n = g.nodes[tryRooms[t]];
                Vector2 tgt = t == 0 ? target : n.centroid;
                // A leg is one pack: its stops should stand together. Every size
                // (the attraction, its alternates, its smaller frames) is tried
                // standing free for the whole leg before any is streamed onto
                // the floor of a stop already finished (the runner swaps it in).
                for (int pass = 0; pass < 2; pass++)
                    foreach (Cand c in w.cands)
                    {
                        if (!FitsRoom(n, c.size)) continue;
                        if (pass == 0 && preferSpot != null && t == 0 && n.rects.Contains(preferSpot.rect) && SameSize(c.size, SizeOf(preferSpot)) && TrySpot(preferSpot, items, chainStart, w.order, out item))
                        { cand = c; roomNode = n.index; offRoute = false; return true; }
                        if (TryPosition(n, c.size, tgt, items, pass == 0 ? avoid : null, chainStart, w.order, pass == 1, out item))
                        { cand = c; roomNode = n.index; offRoute = t >= onRoute; return true; }
                    }
            }
            item = null; cand = null; roomNode = -1; offRoute = false;
            return false;
        }

        private static bool SameSize(Vector2 a, Vector2 b) => Approximately(a, b) || Approximately(a, new Vector2(b.y, b.x));

        private static Vector2 SizeOf(Item it) => (it.lmax - it.lmin) - Vector2.one * SeparationM;

        private static bool TrySpot(Item spot, List<Item> items, int chainStart, int order, out Item item)
        {
            item = new Item { order = order, rect = spot.rect, lmin = spot.lmin, lmax = spot.lmax };
            int maxOv = -1;
            foreach (Item o in items)
                if (o.rect == spot.rect && Overlap(o, item.lmin, item.lmax)) maxOv = Math.Max(maxOv, o.order);
            if (maxOv >= order) return false;
            item.load = Math.Max(chainStart, maxOv + 1);
            return true;
        }

        private static bool Overlap(Item o, Vector2 mn, Vector2 mx) =>
            o.lmin.x < mx.x - 1e-4f && mn.x < o.lmax.x - 1e-4f && o.lmin.y < mx.y - 1e-4f && mn.y < o.lmax.y - 1e-4f;

        /// Grid search over the room's rects (rect-local, on the rect's axes, box
        /// inside the rect). `stream` false: overlap only stops finished before
        /// `chainStart` (and not `avoid`). `stream` true: overlap any earlier
        /// stop; load once the last overlapped one is done; earliest load wins.
        private static bool TryPosition(PlaylistRoomNode n, Vector2 size, Vector2 targetPark, List<Item> items, Item avoid,
            int chainStart, int order, bool stream, out Item best)
        {
            best = null;
            float bestD = float.MaxValue; int bestLoad = int.MaxValue;
            float half = SeparationM * 0.5f;
            foreach (SpaceRect r in n.rects)
            {
                Vector2 tl = r.ParkToRect(targetPark);
                for (int turn = 0; turn < 2; turn++)
                {
                    Vector2 s = turn == 0 ? size : new Vector2(size.y, size.x);
                    if (turn == 1 && Mathf.Abs(size.x - size.y) < 1e-3f) continue;
                    if (s.x > r.w + 1e-3f || s.y > r.d + 1e-3f) continue;
                    float step = Mathf.Clamp(Mathf.Min(r.w, r.d) / 12f, 0.2f, 1.0f);
                    foreach (float cx in Axis(r.x + s.x * 0.5f, r.x + r.w - s.x * 0.5f, step))
                        foreach (float cz in Axis(r.z + s.y * 0.5f, r.z + r.d - s.y * 0.5f, step))
                        {
                            var mn = new Vector2(cx - s.x * 0.5f - half, cz - s.y * 0.5f - half);
                            var mx = new Vector2(cx + s.x * 0.5f + half, cz + s.y * 0.5f + half);
                            int maxOv = -1; bool blocked = false;
                            foreach (Item o in items)
                            {
                                if (o.rect != r || !Overlap(o, mn, mx)) continue;
                                if (!stream && o.order >= chainStart) { blocked = true; break; }
                                maxOv = Math.Max(maxOv, o.order);
                            }
                            if (blocked) continue;
                            if (!stream && avoid != null && avoid.rect == r && Overlap(avoid, mn, mx)) continue;
                            int load = stream ? Math.Max(chainStart, maxOv + 1) : chainStart;
                            if (load > order) continue;
                            float d = Vector2.Distance(new Vector2(cx, cz), tl);
                            if (load < bestLoad || (load == bestLoad && d < bestD - 1e-4f))
                            {
                                bestLoad = load; bestD = d;
                                best = new Item { order = order, rect = r, lmin = mn, lmax = mx, load = load };
                            }
                        }
                }
            }
            return best != null;
        }

        private static IEnumerable<float> Axis(float a, float b, float step)
        {
            if (b < a) { if (b > a - 1e-3f) yield return a; yield break; }
            int n = Mathf.Max(1, Mathf.CeilToInt((b - a) / step));
            for (int i = 0; i <= n; i++) yield return Mathf.Lerp(a, b, i / (float)n);
        }

        /// Unloads, shares, the per-leg schedule and the walk words.
        private static void Finish(PlaylistPlan plan, PlaylistSpec spec, int[] firstOrder, string[] nextApplied, List<Item> items)
        {
            var byOrder = new Dictionary<int, Item>();
            foreach (Item it in items) byOrder[it.order] = it;
            foreach (var s in plan.stops)
            {
                if (!s.placedOk) continue;
                Item a = byOrder[s.order];
                int unload = int.MaxValue;
                foreach (var t in plan.stops)
                {
                    if (t == s || !t.placedOk) continue;
                    Item b = byOrder[t.order];
                    if (a.rect != b.rect || !Overlap(a, b.lmin, b.lmax)) continue;
                    s.sharesWith.Add(t.order);
                    if (s.order < b.load) unload = Math.Min(unload, b.load);
                }
                // One leg at a time: the leg's stops go when the next leg starts.
                if (s.leg + 1 < spec.legs.Count) unload = Math.Min(unload, firstOrder[s.leg + 1]);
                s.unloadAt = unload == int.MaxValue ? -1 : unload;
            }
            int nStops = plan.stops.Count;
            foreach (var l in plan.legs)
            {
                int first = firstOrder[l.leg], last = first + spec.legs[l.leg].stops.Count - 1;
                for (int o = first; o <= last; o++) l.stops.Add(o);
                foreach (var s in plan.stops)
                {
                    if (!s.placedOk) continue;
                    if (s.loadAt == first) l.loadAtStart.Add(s.order);
                    else if (s.loadAt > first && s.loadAt <= last) l.streamIn.Add((s.order, s.loadAt - 1));
                    if (s.unloadAt == first) l.unloadAtStart.Add(s.order);
                }
                string lastRoom = null;
                foreach (int o in l.stops)
                {
                    var s = plan.stops[o];
                    if (s.placedOk && s.roomId != lastRoom && !l.rooms.Contains(s.roomId)) l.rooms.Add(s.roomId);
                    if (s.placedOk) lastRoom = s.roomId;
                }
            }
            // Walk words and backtracking.
            int prevRoute = 0;
            PlaylistPlacedStop prev = null;
            foreach (var l in plan.legs)
            {
                int firstRoute = -1, lastRoute = -1; bool back = false, home = false;
                foreach (int o in l.stops)
                {
                    var s = plan.stops[o];
                    if (!s.placedOk) continue;
                    if (s.homeReturn) home = true;
                    if (firstRoute < 0) firstRoute = s.routeIndex;
                    if (lastRoute >= 0 && s.routeIndex < lastRoute) back = true;
                    lastRoute = s.routeIndex;
                }
                l.walk = home ? "home" : firstRoute < 0 ? "stay" : back ? "back"
                    : (firstRoute == prevRoute && lastRoute == prevRoute && l.leg > 0) ? "stay" : "forward";
                if (lastRoute >= 0) prevRoute = lastRoute;
            }
            foreach (var s in plan.stops)
            {
                if (!s.placedOk) continue;
                if (prev != null && s.routeIndex >= 0 && prev.routeIndex >= 0 && s.routeIndex < prev.routeIndex)
                {
                    var leg = plan.legs[s.leg];
                    bool sameLegBack = leg.walk == "back" && prev.leg == s.leg;
                    bool newLegAfterSwap = s.leg != prev.leg && plan.legs[prev.leg].nextApplied == "swap_in_place";
                    bool allowed = s.homeReturn || sameLegBack || newLegAfterSwap || leg.titleSwitch;
                    if (!allowed) plan.backtracks++;
                }
                prev = s;
            }
            int roomsUsed = 0; var seenRooms = new HashSet<string>();
            foreach (var s in plan.stops) if (s.placedOk && seenRooms.Add(s.roomId)) roomsUsed++;
            float biggest = 0f; foreach (var n in plan.route) biggest = Mathf.Max(biggest, n.largestRectArea);
            plan.layoutMode = roomsUsed > 1 ? "rooms" : biggest >= 30f ? "open" : "stream";
            // A leg's own walk (stop to stop, shortest way) never re-enters a room it left.
            if (plan.graph != null)
                foreach (var l in plan.legs)
                {
                    var visited = new HashSet<int>();
                    int at = -1;
                    foreach (int o in l.stops)
                    {
                        var st = plan.stops[o];
                        if (!st.placedOk || st.roomIndex < 0) continue;
                        if (at < 0) { visited.Add(st.roomIndex); at = st.roomIndex; continue; }
                        if (st.roomIndex == at) continue;
                        List<int> walk = plan.graph.Walk(at, st.roomIndex);
                        for (int q = 1; q < walk.Count; q++) if (!visited.Add(walk[q])) plan.legReentries++;
                        at = st.roomIndex;
                    }
                }
            var sig = new StringBuilder();
            foreach (var s in plan.stops) sig.Append(s.order).Append(':').Append(s.roomId).Append('/').Append(s.rectId).Append('/').Append(s.placed).Append(';');
            plan.signature = sig.ToString();
        }

        private static void Score(PlaylistPlan plan, PlaylistRoomGraph g, List<int> path, int boss, List<StopWork> work)
        {
            float s = 0f;
            var rooms = new HashSet<string>();
            float walk = 0f; PlaylistPlacedStop prev = null;
            foreach (var p in plan.stops)
            {
                if (!p.placedOk) { s -= p.role == "stage" ? 60f : 200f; continue; }
                rooms.Add(p.roomId);
                if (p.streamed) s -= 2f;
                if (p.variant == "alternate") s -= 4f;
                if (p.variant == "shrink") s -= 6f;
                if (p.offRoute) s -= 8f;
                if (prev != null) walk += Vector2.Distance(prev.center, p.center);
                prev = p;
            }
            s += 6f * Math.Min(rooms.Count, plan.stops.Count);
            foreach (var l in plan.legs) if (l.degraded) s -= 5f;
            s -= 10f * plan.backtracks + 15f * plan.legReentries;
            s -= 0.15f * walk;
            if (boss >= 0 && plan.stops[boss].placedOk && plan.stops[boss].roomId != plan.climaxRoomId) s -= 25f;
            plan.score = s;
        }

        // ── names ──

        /// Last path segment, no extension: ".../A_Cannonsnout.prefab" → "A_Cannonsnout".
        public static string Leaf(string s)
        {
            if (string.IsNullOrEmpty(s)) return s;
            int slash = s.LastIndexOf('/');
            string leaf = slash >= 0 ? s.Substring(slash + 1) : s;
            int dot = leaf.LastIndexOf('.');
            return dot > 0 ? leaf.Substring(0, dot) : leaf;
        }

        /// "A_CoinGarden" → "Coin Garden" (Dreamie's name sheets say it better).
        public static string Pretty(string id)
        {
            string s = Leaf(id) ?? "";
            if (s.Length > 2 && s[1] == '_' && char.IsUpper(s[0])) s = s.Substring(2);
            var sb = new StringBuilder();
            for (int i = 0; i < s.Length; i++)
            {
                char c = s[i];
                if (c == '_' || c == '-') { sb.Append(' '); continue; }
                if (i > 0 && char.IsUpper(c) && (char.IsLower(s[i - 1]) || (i + 1 < s.Length && char.IsLower(s[i + 1]) && char.IsUpper(s[i - 1])))) sb.Append(' ');
                sb.Append(c);
            }
            return sb.ToString().Replace("  ", " ").Trim();
        }
    }
}
